-- Create public.scholarships table matching the canonical crawler model
CREATE TABLE IF NOT EXISTS public.scholarships (
    -- Integer primary key generated by scholarships_id_seq
    id SERIAL PRIMARY KEY,

    -- Core identity & provider
    name VARCHAR(300) NOT NULL,
    provider VARCHAR(300),
    host_country VARCHAR(100),

    -- Academic scope (JSONB)
    degree_level JSONB,
    eligible_countries JSONB,
    fields_of_study JSONB,

    -- Dates & timelines
    application_open_date DATE,
    deadline DATE,
    deadline_timezone VARCHAR(100),

    -- Specific eligibility criteria
    minimum_cgpa VARCHAR(100),
    age_limit VARCHAR(200),
    other_eligibility TEXT,
    language_tests JSONB,

    -- Financial & award details
    funding_coverage JSONB,
    award_duration VARCHAR(200),

    -- Application requirements
    required_documents JSONB,
    essay_requirements JSONB,
    referee_requirements JSONB,
    application_fee_and_effort TEXT,

    -- Source verification & provenance (unique constraint)
    official_url TEXT UNIQUE,
    last_verified_at TIMESTAMPTZ
);

-- Comments on table and core columns
COMMENT ON TABLE public.scholarships IS 'Canonical scholarships table holding structured crawler data and platform records';
COMMENT ON COLUMN public.scholarships.id IS 'Primary numeric identifier (INTEGER sequence)';
COMMENT ON COLUMN public.scholarships.name IS 'Scholarship award / programme name';
COMMENT ON COLUMN public.scholarships.official_url IS 'Canonical announcement URL for deduplication';
